// The web app and the engine share one contract: contracts/openapi.json,
// generated by the engine. These checks fail when the two drift apart.
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { FACT_STATE_LABEL } from "@/app/lib/engine/contract";

const openapi = JSON.parse(readFileSync("../contracts/openapi.json", "utf8"));
const schemas = openapi.components.schemas;

describe("engine contract", () => {
  it("keeps the five answer states apart, with a label for each", () => {
    expect([...schemas.FactState.enum].sort()).toEqual(Object.keys(FACT_STATE_LABEL).sort());
    expect(schemas.FactState.enum).toHaveLength(5);
  });

  it("publishes every model the web app relies on", () => {
    for (const name of ["Document", "Fact", "PlanFamily", "Comparison", "MatchScore", "ChatAnswer", "Contact", "Job"]) {
      expect(schemas[name], name).toBeDefined();
    }
  });

  it("generated types match the committed contract", () => {
    const generated = readFileSync("app/lib/engine/contract.gen.ts", "utf8");
    for (const state of schemas.FactState.enum) expect(generated).toContain(`"${state}"`);
    for (const route of schemas.ChatRoute.enum) expect(generated).toContain(`"${route}"`);
  });
});
